API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge_Route_Router, "Edge Route Router", "Envoy Proxy", "Handles external edge routing and ingress traffic for the platform.")
    Component(Auth_Token_Translation_Filter, "Auth & Token Translation Filter", "Go, OAuth2/OIDC, JWT", "Authenticates users via OAuth2/OIDC and translates stateless short-lived tokens containing region and consent scopes.")
    Component(Consent_Enforcement_Interceptor, "Consent Enforcement Interceptor", "Go", "Enforces real-time consent revocation and regulatory checks on incoming requests.")
    Component(Telemetry_Audit_Sidecar, "Telemetry & Audit Sidecar", "OpenTelemetry Collector", "Captures distributed traces and request metadata with persistent disk buffering.")
}

Rel(Edge_Route_Router, Auth_Token_Translation_Filter, "Forwards incoming HTTPS requests for token validation", "HTTPS")
Rel(Auth_Token_Translation_Filter, Consent_Enforcement_Interceptor, "Passes authenticated context for consent verification", "In-process")
Rel(Consent_Enforcement_Interceptor, Telemetry_Audit_Sidecar, "Asynchronously forwards cryptographically verified access logs and telemetry", "gRPC / Async")

@enduml

SFU Media Relay.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(sfu_media_relay, "SFU Media Relay") {
    Component(rtp_rtcp_packet_processor, "RTP/RTCP Packet Processor", "C++, Mediasoup", "Processes and routes RTP/RTCP packets for video and audio streams.")
    Component(simulcast_layer_manager, "Simulcast & Layer Manager", "C++, Mediasoup", "Manages simulcast layers to adapt video quality for low-bandwidth conditions.")
    Component(regional_egress_controller, "Regional Egress Controller", "C++, Mediasoup", "Enforces regional boundary drops and data residency policies.")
    Component(token_validation_signaling_agent, "Token Validation & Signaling Agent", "C++, Mediasoup", "Validates session tokens and handles WebRTC signaling.")
}

Rel(token_validation_signaling_agent, simulcast_layer_manager, "Passes authorized session context", "In-memory C++ API")
Rel(simulcast_layer_manager, rtp_rtcp_packet_processor, "Stream routing rules", "In-memory C++ API")
Rel(sfu_media_relay, regional_egress_controller, "Enforces regional boundary drops", "Internal C++ policy hook")
@enduml

Cloud SQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Cloud SQL container

Container_Boundary(cloud_sql, "Cloud SQL") {
    Component(PgBouncer, "PgBouncer", "PostgreSQL Connection Pooler", "Manages and optimizes high concurrency database connection pooling.")
    Component(Primary_DB_Instance, "Primary DB Instance", "PostgreSQL 15", "Stores regional clinical records, prescriptions, and consent records with schema isolation and RLS.")
}

Rel(PgBouncer, Primary_DB_Instance, "Routes queries over local loopback", "PostgreSQL Protocol / TLS 1.3")

@enduml
